#!/usr/bin/env node
import fs from 'node:fs';import path from 'node:path';import os from 'node:os';import crypto from 'node:crypto';import {spawnSync} from 'node:child_process';import {ROOT,VERSION,HOSTS,corpusDigest,qualificationSubjectDigest,sha256File} from './qualification-lib.mjs';
import {makeTempDir} from './lib/tempdir.mjs';
const a=process.argv.slice(2);const cmd=a[0];const val=k=>{const i=a.indexOf(k);return i>=0?a[i+1]:null;};const sha=p=>crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
if(cmd==='pack'){const dir=val('--evidence-dir')||path.join(ROOT,'evals','qualification');const out=path.resolve(val('--output')||path.join(ROOT,'dist',`live-evidence-v${VERSION}.zip`));const tmp=makeTempDir('agent-sdlc-evidence-');try{const manifest={schema:'agent-sdlc/evidence-bundle/v1',version:VERSION,corpus_sha256:corpusDigest(),qualification_subject_sha256:qualificationSubjectDigest(),files:{}};for(const h of HOSTS){const p=path.join(dir,`${h}-full-v${VERSION}.json`);if(!fs.existsSync(p))continue;const n=`${h}.json`;fs.copyFileSync(p,path.join(tmp,n));manifest.files[h]={file:n,sha256:sha(p)};}fs.writeFileSync(path.join(tmp,'evidence-manifest.json'),JSON.stringify(manifest,null,2)+'\n');fs.mkdirSync(path.dirname(out),{recursive:true});fs.rmSync(out,{force:true});const r=spawnSync('zip',['-qr',out,'.'],{cwd:tmp,encoding:'utf8'});if(r.status!==0)throw new Error(r.stderr||'zip failed');console.log(JSON.stringify({status:'PACKED',output:out,sha256:sha(out),hosts:Object.keys(manifest.files)},null,2));}finally{fs.rmSync(tmp,{recursive:true,force:true});}process.exit(0);} 
if(cmd==='verify'){const bundle=val('--bundle')?path.resolve(val('--bundle')):null;if(!bundle||!fs.existsSync(bundle)){console.error('verify requires --bundle');process.exit(1);}const tmp=makeTempDir('agent-sdlc-evidence-');let errors=[];try{const r=spawnSync('unzip',['-q',bundle,'-d',tmp],{encoding:'utf8'});if(r.status!==0)throw new Error(r.stderr||'unzip failed');const m=JSON.parse(fs.readFileSync(path.join(tmp,'evidence-manifest.json'),'utf8'));if(m.version!==VERSION)errors.push('version mismatch');if(m.corpus_sha256!==corpusDigest())errors.push('corpus digest mismatch');if(m.qualification_subject_sha256!==qualificationSubjectDigest())errors.push('subject digest mismatch');for(const [h,s] of Object.entries(m.files||{})){const p=path.join(tmp,s.file);if(!fs.existsSync(p)||sha(p)!==s.sha256)errors.push(`${h} checksum mismatch`);}console.log(JSON.stringify({status:errors.length?'FAIL':'PASS',errors,bundle_sha256:sha(bundle)},null,2));}catch(e){errors.push(e.message);console.log(JSON.stringify({status:'FAIL',errors},null,2));}finally{fs.rmSync(tmp,{recursive:true,force:true});}process.exit(errors.length?1:0);}console.error('usage: qualification-bundle.mjs pack|verify');process.exit(1);
